"""Lossless scalar export and evidence-grounded reports; no model invocation."""
import pathlib,json,datetime,hashlib,collections,numpy as np,re,os
R=pathlib.Path(os.environ.get('BRIDGE_ROOT','/root/ouro-temporal-bridge-sol-20261117'))
def read(n):return json.loads((R/n).read_text())
def write(n,z): (R/n).write_text(json.dumps(z,indent=2))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def load(folder):return [u for p in sorted((R/folder).glob('TB*.json')) for u in json.loads(p.read_text())['units']]
A=load('results');B=load('B_results');C=load('C_results');assert len(A)==len(B)==len(C)==768
bd={u['id']:u for u in B};cd={u['id']:u for u in C};qs={q['id']:q for q in map(json.loads,(R/'INPUTS.jsonl').read_text().splitlines())}
with (R/'ALL_QUESTION_RESULTS.jsonl').open('w') as f:
 for a in A:f.write(json.dumps({**a,'region_B':bd[a['id']],'path_C':cd[a['id']]},separators=(',',':'))+'\n')
for name,rows in [('B',B),('C',C)]:
 with (R/(name+'_QUESTION_RESULTS.jsonl')).open('w') as f:
  for u in rows:f.write(json.dumps(u,separators=(',',':'))+'\n')
with (R/'REFERENCE_KV_PROVENANCE.jsonl').open('w') as f:
 for p in sorted((R/'results').glob('TB*.json')):
  z=json.loads(p.read_text());f.write(json.dumps({k:z[k] for k in ['pair_id','phase','reference_provenance','canonical_source_KV_hashes']},separators=(',',':'))+'\n')
def margin(u,r):
 x=r['scores']['2']['candidate_logits'];return x[u['answer1']]-x[u['answer0']]
def cluster(rows,values):
 gs=sorted({u['pair_id'] for u in rows});a=np.array([np.mean([v for u,v in zip(rows,values) if u['pair_id']==g]) for g in gs]);rng=np.random.default_rng(2026111711);bs=np.concatenate([a[rng.integers(0,len(a),(250,len(a)))].mean(1) for _ in range(40)])
 return {'mean':float(np.mean(values)),'ci95':np.quantile(bs,[.025,.975]).tolist(),'units':len(rows),'groups':len(gs)}
sem={};sens={}
for phase in ['development','confirmation']:
 aa=[u for u in A if u['split']==phase];bb=[u for u in B if u['split']==phase];cc=[u for u in C if u['split']==phase];sem[phase]={};sens[phase]={}
 collections_by={'A':[(u,u['conditions']) for u in aa],'B':[(u,u['masks']) for u in bb],'C':[(u,u['conditions']) for u in cc]}
 for stage,coll in collections_by.items():
  sem[phase][stage]={};sens[phase][stage]={}
  for condition in coll[0][1]:
   entries=[(u,recs[condition]) for u,recs in coll];effects=[margin(u,r) for u,r in entries]
   strata={key:{str(v):{'n':sum(u[key]==v for u,r in entries),'mean_m':float(np.mean([margin(u,r) for u,r in entries if u[key]==v])),'W1_correct':sum(r['scores']['2']['prediction']==u['answer1'] for u,r in entries if u[key]==v)} for v in sorted({u[key] for u,r in entries})} for key in ['mapping','direction','template','answer1']}
   unique=[(u,r) for u,r in entries if len(r['scores']['2']['ties'])==1];sens[phase][stage][condition]={'all_n':len(entries),'ties':len(entries)-len(unique),'non_tied_n':len(unique),'unique_W1_correct':sum(r['scores']['2']['prediction']==u['answer1'] for u,r in unique),'non_tied_mean_m':float(np.mean([margin(u,r) for u,r in unique])) if unique else None,'tie_policy':'primary uses all units; prediction is first candidate in exact max tie; unique subset descriptive only'}
   # A mapping change changes all cabinet values while keeping first hop and label permutation fixed.
   index={(u['pair_id'],u['id'].split('_')[1],u['direction'],u['mapping']):(u,r) for u,r in entries};pairs=[]
   for k,(u,r) in index.items():
    if k[3]!=0:continue
    v,s=index[(*k[:3],1)];p=r['scores']['2']['prediction'];q=s['scores']['2']['prediction'];world0=qs[next(a['input_W1'] for a in aa if a['id']==u['id'])];world1=qs[next(a['input_W1'] for a in aa if a['id']==v['id'])];pairs.append((p==u['answer1'] and q==v['answer1'],world0['options'][p]!=world1['options'][q]))
   sem[phase][stage][condition]={'strata':strata,'mapping_pairs':len(pairs),'both_mapping_answers_correct':sum(x[0] for x in pairs),'predicted_cabinet_changes_between_disjoint_mappings':sum(x[1] for x in pairs),'warning':'descriptive paired behavior, not independent trials or a separate causal gate'}
 # Non-tie paired contrast sensitivity requires both endpoint conditions unique; retains all primary data above.
 for name,c0,c1 in [('capacity','C00','C01'),('native','C10','C11')]:
  rr=[u for u in aa if all(len(u['conditions'][c]['scores']['2']['ties'])==1 for c in [c0,c1])];sens[phase]['A'][name+'_paired_non_tie']=cluster(rr,[margin(u,u['conditions'][c1])-margin(u,u['conditions'][c0]) for u in rr])
 # Secondary natural-K1-error categories; no filters used for any primary tests.
 for category in ['wrong_right','right_right','right_wrong','wrong_wrong']:
  rr=[u for u in aa if (u['native_W1']['scores']['1']['prediction']==u['answer1'],u['native_W1']['scores']['2']['prediction']==u['answer1'])=={'wrong_right':(False,True),'right_right':(True,True),'right_wrong':(True,False),'wrong_wrong':(False,False)}[category]]
  sens[phase]['A']['native_category_'+category]={'n':len(rr),'native_margin_effect_mean':float(np.mean([margin(u,u['conditions']['C11'])-margin(u,u['conditions']['C10']) for u in rr])) if rr else None}
 # B joint comparisons, descriptive CI only, no region reselection.
 if phase=='development':
  sem[phase]['B_joint_differences']={}
  for hi,lo in [('3','1'),('3','2'),('5','1'),('5','4'),('6','2'),('6','4'),('7','1'),('7','3'),('7','5'),('7','6')]:sem[phase]['B_joint_differences'][hi+'-'+lo]=cluster(bb,[margin(u,u['masks'][hi])-margin(u,u['masks'][lo]) for u in bb])
 # C contrast sign by template and target label is diagnostic, not a new confirmation gate.
 sem[phase]['C_contrast_strata']={}
 for name,left,right in [('restore_early','restore_early','block'),('restore_mid','restore_mid','block'),('restore_late','restore_late','block'),('reverse_early','T','reverse_early'),('reverse_mid','T','reverse_mid'),('reverse_late','T','reverse_late'),('semantic_random','T','random')]:
  sem[phase]['C_contrast_strata'][name]={k:{str(v):float(np.mean([margin(u,u['conditions'][left])-margin(u,u['conditions'][right]) for u in cc if u[k]==v])) for v in sorted({u[k] for u in cc})} for k in ['template','answer1']}
write('SEMANTIC_FACTORIAL_SUMMARY.json',sem);write('TIE_AND_SECONDARY_SENSITIVITY.json',sens)
freeze={n:read(n) for n in ['FREEZE.json','GENERATOR_AUDIT.json','A_EXECUTION_FREEZE.json','A_BACKGROUND_SELECTION.json','B_EXECUTION_FREEZE.json','B_SELECTION.json','B_CONFIRMATION_GATE.json','C_EXECUTION_FREEZE.json','C_RUN_SOURCE_FREEZE.json','SOURCE_RUNTIME.json']};freeze['frozen_inputs']={n:sha(R/n) for n in ['INPUTS.jsonl','UNITS.jsonl','GROUPS.json']};freeze['report_executor']='Sol only; self-audits, no independent agent';write('FROZEN_INPUTS_AND_SELECTION.json',freeze)
def fmt(z,ci='ci95'):return f"{z['mean']:.6f} [{z[ci][0]:.6f}, {z[ci][1]:.6f}]"
def table(headers,rows):return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+''.join('| '+' | '.join(map(str,row))+' |\n' for row in rows)
confA=read('confirmation_A_SUMMARY.json');devA=read('development_A_SUMMARY.json');confB=read('confirmation_B_SUMMARY.json');devB=read('development_B_SUMMARY.json');confC=read('confirmation_C_SUMMARY.json');devC=read('development_C_SUMMARY.json')
Atext='''# Temporal 2x2: frozen two-loop Ouro-1.4B\n\nSol performed implementation, execution, analysis and self-audit. No independent agent participated. 32 new development base groups (256 directed units), 64 disjoint confirmation groups (512 units), eight legal text worlds/group. No native-correct filtering. The same underlying text worlds occur in both directions and are not independent observations. All confidence intervals bootstrap base groups 10,000 times with seed 2026111711.\n\nPrimary margin is logit(correct W1 label) minus logit(correct W0 label), using the four fixed letter-token candidates. Full-vocabulary log probabilities and exact ties are retained. Prediction uses the first candidate among exact ties.\n\n'''
Atext+=table(['Confirmation condition','K2 W1 correct /512','W0 answer','Other','Exact ties','Mean margin'],[[c,z['2']['W1_correct'],z['2']['W0_answers'],z['2']['other_answers'],z['2']['ties'],f"{z['2']['mean_m']:.6f}"] for c,z in confA['conditions'].items()])
Atext+='\n'+table(['Contrast','Development ordinary95%','Confirmation ordinary95%','Confirmation Bonferroni2 97.5%'],[[c,fmt(devA['contrasts'][c]),fmt(confA['contrasts'][c]),fmt(confA['contrasts'][c],'bonferroni2_ci97_5')] for c in ['capacity','native','K1_prior_contribution','interaction']])
Atext+='''\nThe two primary contrasts passed the frozen adjusted-lower-bound and four mapping/direction sign gates in both phases. Only capacity/native are primary; prior contribution and interaction intervals are descriptive. C01 improves the semantic contrast but has only 158/512 W1 predictions, versus 441/512 natural C11. Delayed delivery is limited capacity, not full recovery of natural reasoning. S itself remains natural W1 in both loops, including C01: only delivery into D is delayed.\n\n**Reciprocal-design identity:** C01 forward equals C10 reverse at both full-vocabulary endpoints, and target-margin sign reverses. Pooled capacity equals pooled native and pooled signed interaction is zero by construction. These are not independent convergent tests and do not establish additive computation. Per-orientation effects, full vectors and absolute interaction distributions are preserved in TEMPORAL_SYMMETRY_AUDIT.json. C00 equals W0 as an isolation check, not scientific discovery. C10 introduces an old reference relation against natural W1 downstream states; loss may include semantic incompatibility. It does not demonstrate lack of K1 answer information.\n\n'''
nb=confA['native_text_baselines']['native_W1'];Atext+=f"Natural W1 K1 accuracy {nb['1']['correct']}/512; K2 {nb['2']['correct']}/512. K1 wrong→K2 right: {nb['K1_wrong_K2_right']}; right→wrong: {nb['K1_right_K2_wrong']}. These directed-unit counts cover 512 unique confirmation worlds, each represented once as W1. W0 has the same counts by reciprocal balance.\n\nFull baseline-relative margins, all K1/K2 categories and both native baselines are in the phase A JSON summaries. Unique-answer sensitivity, paired non-tie contrasts, and natural-error strata are in TIE_AND_SECONDARY_SENSITIVITY.json. None replaces the all-unit primary analysis.\n"
(R/'TEMPORAL_2X2_RESULTS.md').write_text(Atext)
Btext='''# Receiver-region experiment\n\nBackground g1=1 was selected using development A only, then checked on confirmation A before B. G_map=[b,query_start), G_query=[query_start,R), G_read=[R,R+1); all punctuation/formatting has explicit membership and these intervals partition D. Bit masks are 1/2/4 respectively. Unopened receivers still read current D states.\n\nAll eight masks were evaluated on development; 0 and 7 reuse A. Before confirmation, mask 1 was selected by the frozen rule: adjusted one-sided Bonferroni6 positive effect, at least80% point retention, all four map/direction signs positive, fewest regions then larger effect. Confirmation evaluated only frozen masks0/1/7. Unexecuted confirmation masks are not negative findings.\n\n'''
Btext+=table(['Dev mask','K2 W1 /256','Effect vs0 ordinary95%','Retention of all-open margin effect'],[[k,z['correct'],fmt(z['effect_vs_allclosed']),f"{100*z['retention_point']:.2f}%"] for k,z in devB['masks'].items()])
Btext+='\n'+table(['Confirm mask','K2 W1 /512','Effect vs0 ordinary95%','Loss vs7 ordinary95%'],[[k,z['correct'],fmt(z['effect_vs_allclosed']),fmt(z['loss_vs_allopen'])] for k,z in confB['masks'].items()])
Btext+='''\nFrozen mask1 passed confirmation. It retains97.441% of the specified K2 reread **margin contrast**, not97.441% of reasoning or accuracy. Native gives441/512 W1 answers; map-only431/512. The small loss interval crosses zero; this is not a formal equivalence test. Development joint-minus-single comparisons and all template/mapping/direction diagnostics are in SEMANTIC_FACTORIAL_SUMMARY.json. This demonstrates that map receivers can carry most of this controlled effect, not exclusive natural routing or a uniquely necessary token.\n''';(R/'RECEIVER_REGION_RESULTS.md').write_text(Btext)
Ctext='''# Actual G→later attention path: fixed coarse intervals\n\nFrozen G=entire map region. H=all later query/options/formatting/read positions. Z uses W0 S KV at all K2 D receivers. T opens S→G only. On T trajectories, block H reads of G using actual Z post-RoPE same-layer-input G K/V; G states and current Q/current remaining D KV remain live. No hidden states or answer logits are copied. Actual G KV equals T and native W1 at every layer, since later H cannot causally influence G.\n\nThree intervals were frozen before any C outcomes: L1–8, L9–16, L17–24. Restore allows current G KV only within that interval. Reverse blocks only that interval. The seven primary contrasts use ordinary95% and two-sided Bonferroni7 99.2857% intervals. Claim an interval only if restore and reverse-block pass adjusted lower>0 and all four map/direction signs in both phases. All intervals retained, no confirmation selection or finer search.\n\n'''
Ctext+=table(['Contrast','Dev mean','Confirmation ordinary95%','Confirmation Bonferroni7','Both-phase individual gate'],[[k,f"{devC['primary_contrasts'][k]['mean']:.6f}",fmt(z),fmt(z,'bonferroni7_ci'),devC['primary_contrasts'][k]['pass'] and z['pass']] for k,z in confC['primary_contrasts'].items()])
Ctext+='\n'+table(['Confirmation condition','K2 W1 /512','Mean margin','Ties'],[[k,z['W1_correct'],f"{z['mean_m']:.6f}",z['ties']] for k,z in confC['conditions'].items()])
for phase,z in [('development',devC),('confirmation',confC)]:Ctext+=f"\n{phase} randomized control: {z['dose']['matched']}/{z['dose']['sites']} row/layer doses within max(1% target,1e-9); maximum relative error {z['dose']['max_relative_error']:.8g}; {len(z['dose']['unmatched_retained'])} unmatched rows retained and listed in phase summary.\n"
Ctext+='''\nDose is the actual BF16 **SDPA-output difference**, flattened across heads at each H row, before the unchanged output projection. It is not a norm match on projected residual states or logits. Targets are measured on T, per unit/layer/row, without gold answers. A seeded feature permutation supplies an unrelated direction from the current allowed-vs-blocked difference; zero directions use seeded Gaussian fallback. The closest BF16 realization is searched with fixed bracketing/bisection and all mismatches retained. The control matches T across all24 H layers; it does not separately dose-match each eight-layer partial restore. Thus T-vs-random supports whole-channel directional specificity, not independent semantic specificity of each interval.\n\n`counterfactual_T_writeback_norms` in non-T records means a locally prospective allowed-G-vs-Z_G row difference on that condition's current trajectory; only T observe records are actual T targets. Random `dose.target` explicitly holds actual T targets.\n\nFull block reproduces Z; full restore reproduces T. These are channel-construction and consistency identities, not independent path-discovery evidence. Partial restores, reverse blocks, factorial semantic signs and held-out confirmation supply scientific evidence. The experiment localizes a controlled map→later attention influence in K2, without identifying particular heads, exact S→map entry layers, a unique symbolic algorithm, or whether G composes versus relays an answer-relevant computation.\n''';(R/'PATH_BLOCK_AND_RESTORE.md').write_text(Ctext)
Stext='''# Semantic factorial checks\n\nAll96 base groups include first-hop2×second-hop mapping2×reversed option orders2 legal worlds, both directed replacements per mapping/label order. Four cabinet values are distinct in each group; changing second-hop mapping changes both correct cabinet values while preserving first-hop identity. All pairs have byte-identical D token IDs, equal lengths/positions/boundaries and symbolically verified answers.32 development objectsA–D;64 confirmation objectsE–H; shuffled mapping-clause order; three wordings including stored/contained/ultimately-encloses. This is a new fixed combination split within an already studied synthetic family, not a claim that pretraining never saw these concepts.\n\nSEMANTIC_FACTORIAL_SUMMARY.json reports for every condition: both mapping blocks, both relation directions, all templates, all desired labels, paired behavior under changing mapping, plus development joint-mask differences and C contrast diagnostics. Paired mapping success is descriptive and not treated as independent observations. All primary margins are oriented to the symbolically expected *changed composition*, not a fixed letter.\n\n'''
Stext+=table(['Confirmation contrast','Map0 Dir0','Map0 Dir1','Map1 Dir0','Map1 Dir1'],[[k,*[f"{v:.6f}" for v in z['mapping_direction_means'].values()]] for k,z in confC['primary_contrasts'].items()])
Stext+='\n'+table(['Confirmation A contrast','Desired A','Desired B','Desired C','Desired D'],[[k,*[f"{v:.6f}" for v in confA['contrasts'][k]['by_desired_label'].values()]] for k in ['capacity','native']])
Stext+='''\nNo primary samples were removed for native correctness or ties. Ties are exact BF16 candidate-score equalities and remain in all primary margins. Non-tie and native-error strata are secondary descriptive checks. Source S contains demonstrations, the complete first-hop clause and its punctuation/newline. Actual technical S KV is exactly invariant to future map/option changes at every layer in both loops; prefix-difference profiles are high-dimensional causal-state diagnostics, not probes of an assumed independent variable.\n\nPrior evidence remains unchanged: boundary-state exchange has partial semantic effects; a previously nominated single attention edge did not establish reliable semantic specificity. This does not prove absence of circuits or necessarily distributed computation. No ARC Test was run in this study.\n''';(R/'SEMANTIC_FACTORIAL_RESULTS.md').write_text(Stext)
win=[name for name in ['early','mid','late'] if all(devC['primary_contrasts'][k]['pass'] and confC['primary_contrasts'][k]['pass'] for k in ['restore_'+name+'_vs_block','T_vs_reverse_'+name])]
conclusion=f'''# Final mechanistic conclusion\n\n**在该关系任务族和指定干预下的因果信息整合机制**：Ouro-1.4B 第二轮可通过读取第一步关系前缀，更新第二步映射区域，再通过映射区域到后续问题/选项/读出位置的注意力读取影响组合答案。确认支持的粗层区间：{', '.join(win)}（early=L1–8, mid=L9–16, late=L17–24）。这是一条得到受控因果证据支持的路径，不是完整、唯一的推理算法。\n\n1. **延迟进入D的能力**：C01−C00确认效应 {fmt(confA['contrasts']['capacity'])}；W1正确158/512，低于自然441/512。S从始至终保持自然W1；被延迟的是传入D的差异。\n2. **自然K1后的重读敏感性**：C11−C10确认效应 {fmt(confA['contrasts']['native'])}。K1自身238/512正确；K2增加到441/512。C10的旧关系与自然D可能冲突，不能将效应全部解释为信息缺失。双向汇总与capacity数值相等是设计恒等关系，并非两份独立证据。\n3. **入口区域**：仅开放S→整个映射区域，确认effect {fmt(confB['masks']['1']['effect_vs_allclosed'])}，保留指定全开margin效应97.441%，正确431/512。未证明自然模型排他使用该区域。\n4. **继续传递**：局部恢复和反向阻断在确认集复现固定粗区间效应。最强的L9–16恢复效应 {fmt(confC['primary_contrasts']['restore_mid_vs_block'],'bonferroni7_ci')}；反向阻断损失 {fmt(confC['primary_contrasts']['T_vs_reverse_mid'],'bonferroni7_ci')}。完整通道随机方向控制与T的差异 {fmt(confC['primary_contrasts']['T_vs_matched_random'],'bonferroni7_ci')}。完整阻断=Z和完整恢复=T仅为校验。\n5. **语义组合**：两个独立值域的第二步映射、双向第一步替换、反转标签、三种措辞均保留；主要正效应通过四个map×direction符号门槛。具体分层及失败区间完整公开。没有预设或训练独立中间变量。\n6. **尚未识别**：S→map具体在哪些层形成，map局部执行组合还是传递别处形成的计算，后续H中具体接收位置/Attention Heads、唯一低维表示及算法，均未解决。不能扩展到全部ARC提升，也不能声称K1所有状态缺少答案信息。\n\n权重冻结，无训练、无准确率调参、无新head或层细分搜索、无ARC Test；单4090，完整180分钟上限内。32开发+64确认base groups共768 directed units，按base group bootstrap，保留所有失败和并列。全部实施、分析及数值自审均由Sol完成；无独立代理复核。\n\nSee TEMPORAL_2X2_RESULTS.md, RECEIVER_REGION_RESULTS.md, PATH_BLOCK_AND_RESTORE.md, SEMANTIC_FACTORIAL_RESULTS.md, and all machine-readable summaries/audits.\n'''
(R/'FINAL_MECHANISTIC_CONCLUSION.md').write_text(conclusion)
print('OUTPUTS_BUILT',len(A),'confirmed_windows',win,'bytes_ALL',(R/'ALL_QUESTION_RESULTS.jsonl').stat().st_size)
# Post-run diagnostic of realized randomized-control doses. Does not change any gate.
if (R/'RANDOM_DOSE_AUDIT.json').exists():
 d=read('RANDOM_DOSE_AUDIT.json')['confirmation'];p=R/'PATH_BLOCK_AND_RESTORE.md';s=p.read_text();s+=f"\nActual confirmation dose diagnostic: {100*d['matched_1pct_or_absolute']/d['sites']:.3f}% within the frozen1%/absolute tolerance; {d['exceed_relative_10pct']}/{d['sites']} rows exceed10% relative error; sum absolute norm errors / sum target norms={100*d['absolute_norm_error_sum_div_target_norm_sum']:.5f}%. Full quantiles and layer profiles are in RANDOM_DOSE_AUDIT.json. All rows remain included. The control approximates matched perturbation size; it is not an exact-dose null. This limits directional-specificity interpretation, especially individual low-amplitude rows.\n";p.write_text(s)
 p=R/'FINAL_MECHANISTIC_CONCLUSION.md';p.write_text(p.read_text()+f"\n随机方向对照为近似幅度匹配：确认集{100*d['matched_1pct_or_absolute']/d['sites']:.2f}%行达到预设容差，{d['exceed_relative_10pct']}行相对误差超过10%，全部保留；总绝对范数误差占目标范数和的{100*d['absolute_norm_error_sum_div_target_norm_sum']:.5f}%。这一对照支持完整通道方向作用的判断，但不构成每个局部区间的精确幅度语义对照。\n")
